-- 订单库增量 DDL：为 d_order 增加「节目数据同步 outbox」字段。
-- 新部署直接使用更新后的 sql/cloud/ticketflow_order_*.sql，无需执行本脚本。
--
-- 变更内容：支付/取消订单后把「Redis 已收敛的节目数据」同步到节目服务 DB 的动作，
-- 从原来 afterCommit 里的一次 Feign（失败只打日志）改成写在 d_order 同一行上的 outbox：
--   program_sync_status  0 无需同步 / 1 待同步 / 2 已同步 / 3 死信
--   program_sync_attempts / program_sync_next_time / program_sync_payload / program_sync_error
-- 复用 d_order 而不是新表：入队 UPDATE 必须和订单状态 CAS 落在同一物理分片，才能在一个本地事务里原子提交。
-- 索引 idx_program_sync 供重试任务按 (状态, 下次同步时间) 扫描；该扫描不带分片键，会路由到全部 16 张物理表。
--
-- 执行顺序：先执行本脚本，再发布带 outbox 代码的 order-service。
-- 未执行本脚本就发布，订单状态更新会因缺少列而失败（支付回调直接报错）。

-- ==================== ticketflow_order_0 ====================
USE ticketflow_order_0;
ALTER TABLE d_order_0 ADD COLUMN `program_sync_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '节目数据同步状态 0:无需同步 1:待同步 2:已同步 3:死信', ADD COLUMN `program_sync_attempts` int(3) NOT NULL DEFAULT '0' COMMENT '节目数据同步已尝试次数', ADD COLUMN `program_sync_next_time` datetime DEFAULT NULL COMMENT '节目数据下次允许同步的时间', ADD COLUMN `program_sync_payload` text COMMENT '待同步给节目服务的 ProgramOperateDataDto JSON', ADD COLUMN `program_sync_error` varchar(500) DEFAULT NULL COMMENT '最近一次同步失败原因', ADD INDEX `idx_program_sync` (`program_sync_status`,`program_sync_next_time`);
ALTER TABLE d_order_1 ADD COLUMN `program_sync_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '节目数据同步状态 0:无需同步 1:待同步 2:已同步 3:死信', ADD COLUMN `program_sync_attempts` int(3) NOT NULL DEFAULT '0' COMMENT '节目数据同步已尝试次数', ADD COLUMN `program_sync_next_time` datetime DEFAULT NULL COMMENT '节目数据下次允许同步的时间', ADD COLUMN `program_sync_payload` text COMMENT '待同步给节目服务的 ProgramOperateDataDto JSON', ADD COLUMN `program_sync_error` varchar(500) DEFAULT NULL COMMENT '最近一次同步失败原因', ADD INDEX `idx_program_sync` (`program_sync_status`,`program_sync_next_time`);
